        "content": "When you are furious about an unfair workplace review or terrified about a financial loss, an AI companion acts as your personal Seneca or Epictetus. It intercepts your raw emotional rage, validates your initial human reaction, and Socraticly interrogates your assumptions through the lens of the Dichotomy of Control."
