        "content": "> **Prompt for AI:** > *\"Today, I anticipate dealing with difficult people, unexpected delays, and high pressure in [insert context, e.g., corporate restructuring]. Guide me through Marcus Aurelius' morning preparation: remind me why their behavior stems from ignorance of good and evil, and help me define how my Inner Citadel remains uninjured regardless of what they say.\"*"
